/**
 * Owns Wolf Beauty's existing private-state slot and ordinary charm history writes.
 * Inputs are the original role or captured state plus the accepted nullable target/day;
 * outputs retain the same stored reference, assignment order and partial writes.
 * State data retains death-link policy, nullable target/day and nullable-target history.
 * Callers own target qualification, charm binding and public/private publication;
 * this owner never repeats those checks, refunds effects or changes death policy.
 * Pure payload/read data structures belong to the neutral role-state data owner;
 * this leaf retains original live references and concrete installation/commit operations.
 */
import type { WolfBeautyState, WolfBeautyReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";

export function setWolfBeautyState(
  roleComp: RoleComponent,
  state: WolfBeautyState,
): WolfBeautyReadState {
  (roleComp.privateState as { wolf_beauty: WolfBeautyState })["wolf_beauty"] = state;
  return state;
}

export function getWolfBeautyState(roleComp: RoleComponent): WolfBeautyReadState | undefined {
  return (roleComp.privateState as { readonly wolf_beauty?: unknown })["wolf_beauty"] as
    WolfBeautyReadState | undefined;
}

/** The caller retains every preflight and subsequent use/effect/publication operation. */
export function recordCharmSelection(
  state: WolfBeautyReadState,
  targetId: EntityId | null,
  day: number,
): void {
  (state as { targetId: EntityId | null }).targetId = targetId;
  (state as { lastActedDay: number | null }).lastActedDay = day;
  (state.history as WolfBeautyState["history"]).push({ day, targetId });
}

/**
 * 负责狼美人批量死亡贡献的领取、梦阻断、原提案写入及实际标死后的关系事实发布。
 * 输入为 hook 捕获的原绑定／夜间旗标，以及晚读的原命令和结算查询；输出是追加原因、
 * 公开关联与本族发布回调。绑定和 claimed 回执只保在本闭包，不进入通用 hook 载荷或归档。
 * relation 独自拥有 resolved／applied；先领取再保护，阻断或发布失败保留已付与已提交前缀。
 * 本模块不标死、选择阶段、消费枪或遗言许可；规则见 docs/rules/awa-wolf-beauty-v1.md。
 */
import { DeathCause, type EntityId } from "@ai-werewolf-arena/game-contract";
import type { DeathWaveContribution } from "../../hooks/death-wave-contribution";
import type {
  attemptCharmTrigger,
  commitCharmDeath,
  CharmBinding,
  CharmClaimReceipt,
} from "./relation";

interface WolfBeautyDeathCommands {
  readonly attemptCharmTrigger: typeof attemptCharmTrigger;
  readonly commitCharmDeath: typeof commitCharmDeath;
}

/** 一次 hook 的原 proposal 数组；未领取绑定仍由唯一 relation 库存持有，不复制原体。 */
export function createWolfBeautyDeathContribution(
  proposals: readonly { readonly binding: CharmBinding; readonly nightEffect: boolean }[],
  commands: WolfBeautyDeathCommands,
): DeathWaveContribution {
  return {
    prepare(
      runtime,
      proposed,
      proposedSources,
      nightTargets,
      allSources,
      nativeHunterShotTargets,
      seen,
    ) {
      const charmTriggers: CharmDeathWaveTrigger[] = [];
      for (const proposal of proposals) {
        const binding = proposal.binding;
        // 具体关系 owner 在原位置领取和查询保护；延迟 World，permit 失败不新增读取。
        // 先取原命令再裸调用，保留 callee 读取时点与 receiver；之后才求值原参数。
        const attemptCharmTrigger = commands.attemptCharmTrigger;
        const trigger = attemptCharmTrigger(
          binding,
          allSources,
          nativeHunterShotTargets,
          seen,
          () => runtime.world,
          () => proposal.nightEffect && runtime.blocksNightLinkedDeath(() => binding.targetId),
        );
        if (!trigger) continue;
        if (trigger.kind === "blocked") {
          runtime.events.push({
            timestamp: Date.now(),
            type: "charm_blocked",
            payload: {
              actorId: binding.actorId,
              targetId: binding.targetId,
              reason: "night_protection",
            },
          });
          continue;
        }
        charmTriggers.push({ binding, receipt: trigger });
        if (!proposed.includes(binding.targetId)) proposed.push(binding.targetId);
        proposedSources[binding.targetId] = [
          ...new Set([...(proposedSources[binding.targetId] ?? []), DeathCause.Charm]),
        ];
        if (proposal.nightEffect) nightTargets.push(binding.targetId);
      }
      // 完整批量准备之后才读目标，保持原 triggers.map 时点；内部绑定和回执不交给引擎。
      const linkedDeaths = charmTriggers.map(({ binding }) => ({
        targetId: binding.targetId,
        addedCauses: [DeathCause.Charm],
        publicAdditionalDeath: true,
      }));
      return {
        linkedDeaths,
        // 原实际标死之后才核 applied；事件失败不能撤销已 applied 或既有事件。
        publishAfterDeaths() {
          for (const { binding, receipt } of charmTriggers) {
            const commitCharmDeath = commands.commitCharmDeath;
            const applied = commitCharmDeath(runtime.world, receipt);
            if (applied?.kind === "applied")
              runtime.events.push({
                timestamp: Date.now(),
                type: "charm_death",
                payload: { actorId: binding.actorId, targetId: binding.targetId },
              });
          }
        },
      };
    },
  };
}

/** 仅在本族准备／发布闭包内传递，具体权威回执不能替代死亡提交。 */
interface CharmDeathWaveTrigger {
  readonly binding: CharmBinding;
  readonly receipt: CharmClaimReceipt;
}

/**
 * 负责胜利条件的有序委托与覆盖结果优先选择。输入为原 World、只读条件 ID、检查点及覆盖数据；输出为首个原判定或 null。
 * 本入口不改变参数数组或封存结果，真实检查点执行与终局仍由 PhaseManager 持有。
 */
import type { VictoryCheckpoint } from "@ai-werewolf-arena/game-contract";
import { WinDecision, WinCondition } from "../model";
import { World } from "../world";

/**
 * 胜负判定注册中心抽象：由机制层实现并在装配期注入。
 */
export interface WinConditionEvaluator {
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null;
}

/**
 * 胜负条件入口：委托机制层 WinConditionRegistry。
 */
export class ConditionRegistry {
  private readonly winRegistry: WinConditionEvaluator;

  constructor(winRegistry: WinConditionEvaluator) {
    this.winRegistry = winRegistry;
  }

  /**
   * 按指定胜负模式执行胜负判定。
   */
  evaluate(
    world: World,
    condition: WinCondition,
    checkpoint?: VictoryCheckpoint,
  ): WinDecision | null {
    return this.winRegistry.evaluate(world, condition, checkpoint);
  }

  /**
   * 按给定顺序评估多个胜负模式，命中即返回。
   */
  evaluateMany(
    world: World,
    conditions: readonly WinCondition[],
    checkpoint?: VictoryCheckpoint,
    overrides: Partial<Record<WinCondition, WinDecision>> = {},
  ): WinDecision | null {
    for (const condition of conditions) {
      const result = overrides[condition] ?? this.evaluate(world, condition, checkpoint);
      if (result) {
        return result;
      }
    }
    return null;
  }
}

/**
 * 负责把已接受的胜利判定投影成结构化结果。输入为当前胜利归属、已判目标与原因，输出保留获胜成员和 claim 数据。
 * 本模块不重新选择屠边政策、不修改玩家组件；判胜仍由原胜利条件与检查点负责。
 */
import type { GameOutcome, VictoryClaim, VictoryTarget } from "@ai-werewolf-arena/game-contract";
import { COMPONENT, type WinDecision, type World } from "../../../core/domain";
import type { VictoryComponent } from "../../../core/domain/components/victory";
import { readGameOutcome } from "@ai-werewolf-arena/replay-contract";

/** 成员来自明确 Victory 组件，不根据角色或真实阵营推断。 */
export function victoryDecision(
  world: World,
  primary: VictoryTarget,
  reason: string,
  additional: readonly VictoryTarget[] = [],
): WinDecision {
  const claim = (target: VictoryTarget): VictoryClaim => {
    const winningPlayerIds = world.entityIds().filter((id) => {
      if (target.kind === "individual" && id !== target.playerId) return false;
      return (
        world
          .getComponent(id, COMPONENT.Victory)
          ?.affiliations.some(
            (member) =>
              (target.kind === "faction" &&
                member.kind === "faction" &&
                target.faction === member.faction) ||
              (target.kind === "individual" &&
                member.kind === "individual" &&
                target.goalId === member.goalId) ||
              (target.kind === "relationship" &&
                member.kind === "relationship" &&
                target.groupId === member.groupId),
          ) === true
      );
    });
    if (target.kind !== "faction" && winningPlayerIds.length === 0)
      throw new Error("victory_target_has_no_members");
    return { ...target, winningPlayerIds };
  };
  const first = claim(primary),
    others = additional.map(claim);
  const outcome: GameOutcome = {
    kind: "victory",
    primary: first,
    additional: others,
    winningPlayerIds: [
      ...new Set([first, ...others].flatMap((item) => item.winningPlayerIds)),
    ].sort((a, b) => a - b),
  };
  if (typeof reason !== "string" || reason.length === 0) throw new Error("victory_reason_invalid");
  return {
    winner: primary.kind === "faction" ? (primary.faction as WinDecision["winner"]) : null,
    reason,
    outcome: readGameOutcome(outcome, world.entityIds()),
  };
}

/**
 * 场景测试验证狼美人关系链与判胜。输入保留魅惑／死因／locale／胜利参数及受控迟到提案；原字面回执、引用／getter／错误轨迹、事实和状态是预期。实际中心 DeathResolution（含异步撤销 hook）及 PhaseManager 周期结算复合死因、枪、魅惑、警徽与有序胜利；模型由受控 provider 替代，生产输出不生成新 golden。
 */
import { createAliveComponent } from "../../../../src/game/observation/component-presentation";
import { PotionType } from "../../../../src/core";
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import {
  Role,
  Camp,
  Phase,
  COMPONENT,
  WinCondition,
  KnightDuelWindow,
  type BoardConfig,
  type ActionRequest,
  type RoleComponent,
} from "../../../../src/core";
import { sixPlayerMvpConfig } from "../../../../src/runtime/scenarios/six_player_mvp";
import { getWolfBeautyState } from "../../../../src/game/mechanisms/roles/wolf_beauty/ports";
import { ActionReception } from "../../../../src/game/gateway/action-reception";
import { buildAgentVisibleEventFeed } from "../../../../src/game/engine/agent_visible_event_feed";
import { bindCharm } from "../../../../src/game/mechanisms/roles/wolf_beauty/relation";
import { DeathCause, type GameEvent } from "../../../../src/core";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";

import { DeathResolution } from "../../../../src/game/engine/death_resolution";
import { EventRegistry } from "../../../../src/game/engine/event_registry";
import { HookRegistry } from "../../../../src/game/mechanisms/hooks/hook_registry";
import { wolfBeautyDeathHook } from "../../../../src/game/mechanisms/roles/wolf_beauty/death_hook";

const deck = [Role.WolfBeauty, Role.Wolf, Role.Witch, Role.Knight, Role.Villager, Role.Villager];

const board = (roles = deck): BoardConfig => ({
  ...sixPlayerMvpConfig,
  winConditions: [WinCondition.SlaughterSide],
  roleSetups: [...new Set(roles)].map((role) => ({
    role,
    count: roles.filter((item) => item === role).length,
  })),
  knight: { enabledWindows: [KnightDuelWindow.AfterSpeeches] },
});

const role = (game: ReturnType<typeof bootstrapGame>, id: number) =>
  game.world.getComponent(id, COMPONENT.Role)!;

for (const mutation of [
  "replace_life",
  "revive",
  "clear_binding",
  "replace_state",
  "change_policy",
] as const)
  test(`${mutation}: a revoked real hook proposal cannot kill or add sources/public facts after its await`, async () => {
    const game = bootstrapGame(board(), { fixedRoles: deck }),
      events: GameEvent[] = [],
      state = getWolfBeautyState(role(game, 1))!;
    (state as { targetId: number | null }).targetId = 5;
    bindCharm(game.world, 1, 5);
    const original = game.world.getComponent(5, COMPONENT.Alive)!;
    const registry = new EventRegistry(
      new HookRegistry(
        [],
        [
          async (...args) => {
            const result = await wolfBeautyDeathHook(...args);
            queueMicrotask(() => {
              if (mutation === "replace_life")
                game.world.addComponent(5, COMPONENT.Alive, createAliveComponent());
              if (mutation === "revive") {
                original.alive = false;
                original.alive = true;
              }
              if (mutation === "change_policy")
                (
                  state as {
                    deathLinkPolicy:
                      "awa_exile_poison_v1" | "heroes_s7_2017_exile_hunter_v1" | undefined;
                  }
                ).deathLinkPolicy = "heroes_s7_2017_exile_hunter_v1";
              if (mutation === "clear_binding") bindCharm(game.world, 1, null);
              if (mutation === "replace_state")
                (role(game, 1).privateState as Record<string, unknown>).wolf_beauty = {
                  targetId: null,
                  lastActedDay: null,
                  history: [],
                };
            });
            return result;
          },
        ],
      ),
    );
    const resolution = new DeathResolution(game.world, events, new ToolGateway(), registry, {
      day: 1,
      phase: Phase.Voting,
      gameOver: false,
      result: null,
    });
    await resolution.resolve(
      [1],
      { 1: [DeathCause.Exile] },
      {
        async getAction() {
          return { name: "speak", args: { text: "Original words" } };
        },
      },
      Phase.Voting,
      Phase.Voting,
    );
    expect(game.world.getComponent(5, COMPONENT.Alive)!.alive).toBe(true);
    expect(original.alive).toBe(true);
    expect(
      events.some((event) =>
        ["additional_deaths", "charm_death", "charm_blocked"].includes(event.type),
      ),
    ).toBe(false);
  });

test("same-wave knife Hunter retains already valid initial words, while a later charm cause suppresses its pending gun", async () => {
  const fixed = [Role.WolfBeauty, Role.Wolf, Role.Witch, Role.Knight, Role.Hunter, Role.Villager],
    game = bootstrapGame(board(fixed), { fixedRoles: fixed });
  let guns = 0;
  await game.phaseManager.runSingleCycle({
    async getAction(request) {
      if (request.allowedTools.includes("speak_to_wolves"))
        return { name: "speak_to_wolves", args: { text: "End", end_chat: true } };
      if (request.allowedTools.includes("kill_vote"))
        return { name: "kill_vote", args: { target_id: 5, abstain: false } };
      if (request.allowedTools.includes("charm")) return { name: "charm", args: { target_id: 5 } };
      if (request.allowedTools.includes("use_potion"))
        return { name: "use_potion", args: { target_id: 1, potion_type: PotionType.Poison } };
      if (request.allowedTools.includes("speak")) return { name: "speak", args: { text: "Raw" } };
      if (request.allowedTools.includes("duel")) return null;
      if (request.allowedTools.includes("shoot")) {
        guns++;
        throw new Error("charm_forbids_pending_gun");
      }
      if (request.allowedTools.includes("vote"))
        return { name: "vote", args: { target_id: 2, abstain: false } };
      throw new Error(`unexpected:${request.context.stage}`);
    },
  });
  const events = game.phaseManager.getEvents();
  expect(guns).toBe(0);
  expect(
    events
      .filter((event) => event.type === "last_words_spoken")
      .map((event) => event.payload.playerId),
  ).toEqual([1, 5, 2]);
  expect(
    events.filter((event) => event.type === "charm_death").map((event) => event.payload),
  ).toEqual([{ actorId: 1, targetId: 5 }]);
  expect(events.some((event) => event.type === "additional_deaths")).toBe(false);
  expect(game.world.getAliveEntityIds()).toEqual([3, 4, 6]);
  expect(game.phaseManager.getSnapshot().result?.winner).toBe(Camp.Good);
});

for (const lastVillager of [false, true])
  test(`last Beauty villager side/${lastVillager}: actual side completion is required for the special victory`, async () => {
    const fixed = lastVillager
        ? [Role.WolfBeauty, Role.Witch, Role.Knight, Role.Knight, Role.Seer, Role.Villager]
        : [Role.WolfBeauty, Role.Witch, Role.Knight, Role.Villager, Role.Villager, Role.Villager],
      game = bootstrapGame(board(fixed), { fixedRoles: fixed });
    await game.phaseManager.runSingleCycle({
      async getAction(request) {
        if (request.allowedTools.includes("speak_to_wolves"))
          return { name: "speak_to_wolves", args: { text: "End", end_chat: true } };
        if (request.allowedTools.includes("kill_vote"))
          return { name: "kill_vote", args: { target_id: 3, abstain: false } };
        if (request.allowedTools.includes("charm"))
          return { name: "charm", args: { target_id: lastVillager ? 6 : 4 } };
        if (request.allowedTools.includes("use_potion"))
          return { name: "use_potion", args: { target_id: 2, potion_type: PotionType.None } };
        if (request.allowedTools.includes("check_identity"))
          return { name: "check_identity", args: { target_id: 1 } };
        if (request.allowedTools.includes("duel")) return null;
        if (request.allowedTools.includes("speak")) return { name: "speak", args: { text: "Raw" } };
        if (request.allowedTools.includes("vote"))
          return { name: "vote", args: { target_id: 1, abstain: false } };
        throw new Error(`unexpected:${request.context.stage}`);
      },
    });
    expect(game.phaseManager.getSnapshot().result).toMatchObject({
      winner: lastVillager ? Camp.Wolf : Camp.Good,
      reason: lastVillager ? "wolf_beauty_last_exile" : "all_wolves_eliminated",
    });
    expect(game.world.getAliveEntityIds()).toEqual(lastVillager ? [2, 4, 5] : [2, 5, 6]);
  });

for (const cycle of [false, true])
  test(`multiple Beauties/${cycle}: independent bindings terminate and Charm alone cannot recursively trigger another Beauty`, async () => {
    const fixed = cycle
        ? [Role.WolfBeauty, Role.WolfBeauty, Role.Witch, Role.Witch, Role.Villager, Role.Villager]
        : [Role.WolfBeauty, Role.WolfBeauty, Role.Witch, Role.Knight, Role.Hunter, Role.Villager],
      game = bootstrapGame(board(fixed), { fixedRoles: fixed });
    await game.phaseManager.runSingleCycle({
      async getAction(request) {
        if (request.allowedTools.includes("speak_to_wolves"))
          return { name: "speak_to_wolves", args: { text: "End", end_chat: true } };
        if (request.allowedTools.includes("kill_vote"))
          return { name: "kill_vote", args: { target_id: cycle ? null : 6, abstain: cycle } };
        if (request.allowedTools.includes("charm"))
          return { name: "charm", args: { target_id: request.actorId === 1 ? 2 : cycle ? 1 : 5 } };
        if (request.allowedTools.includes("use_potion"))
          return {
            name: "use_potion",
            args: { target_id: request.actorId === 3 ? 1 : 2, potion_type: PotionType.Poison },
          };
        if (request.allowedTools.includes("speak")) return { name: "speak", args: { text: "Raw" } };
        throw new Error(`unexpected:${request.context.stage}`);
      },
    });
    const events = game.phaseManager.getEvents();
    expect(
      events
        .filter((event) => event.type === "charm_death")
        .map((event) => [event.payload.actorId, event.payload.targetId]),
    ).toEqual(
      cycle
        ? [
            [1, 2],
            [2, 1],
          ]
        : [[1, 2]],
    );
    expect(
      events
        .filter((event) => event.type === "additional_deaths")
        .map((event) => event.payload.deaths),
    ).toEqual(cycle ? [] : [[2]]);
    expect(events.some((event) => event.type === "hunter_shot")).toBe(false);
    expect(game.world.getAliveEntityIds()).toEqual(cycle ? [3, 4, 5, 6] : [3, 4, 5]);
    expect(game.phaseManager.getSnapshot().result?.winner).toBe(Camp.Good);
  });

for (const heal of [false, true])
  test(`Night guard/heal/${heal}: ordinary protection never blocks the charm cause or grants the dying Hunter a gun`, async () => {
    const fixed = [
        Role.WolfBeauty,
        Role.Wolf,
        Role.Witch,
        Role.Guard,
        Role.Witch,
        Role.Hunter,
        Role.Villager,
        Role.Villager,
      ],
      game = bootstrapGame({ ...board(fixed), boardSize: 8 }, { fixedRoles: fixed });
    let guns = 0;
    await game.phaseManager.runSingleCycle({
      async getAction(request) {
        if (request.allowedTools.includes("speak_to_wolves"))
          return { name: "speak_to_wolves", args: { text: "End", end_chat: true } };
        if (request.allowedTools.includes("kill_vote"))
          return { name: "kill_vote", args: { target_id: 6, abstain: false } };
        if (request.allowedTools.includes("guard"))
          return { name: "guard", args: { target_id: 6, abstain: false } };
        if (request.allowedTools.includes("charm"))
          return { name: "charm", args: { target_id: 6 } };
        if (request.allowedTools.includes("use_potion"))
          return request.actorId === 5
            ? { name: "use_potion", args: { target_id: 1, potion_type: PotionType.Poison } }
            : {
                name: "use_potion",
                args: {
                  target_id: heal ? 6 : 3,
                  potion_type: heal ? PotionType.Heal : PotionType.None,
                },
              };
        if (request.allowedTools.includes("speak")) return { name: "speak", args: { text: "Raw" } };
        if (request.allowedTools.includes("shoot")) {
          guns++;
          throw new Error("charm_forbids_gun");
        }
        if (request.allowedTools.includes("vote"))
          return { name: "vote", args: { target_id: 2, abstain: false } };
        throw new Error(`unexpected:${request.context.stage}`);
      },
    });
    expect(guns).toBe(0);
    expect(
      game.phaseManager
        .getEvents()
        .filter((event) => event.type === "charm_death")
        .map((event) => event.payload.targetId),
    ).toEqual([6]);
    expect(game.world.getAliveEntityIds()).toEqual([3, 4, 5, 7, 8]);
    expect(game.phaseManager.getSnapshot().result?.winner).toBe(Camp.Good);
  });

