      reason: wolf ? "wolf_beauty_last_exile" : "all_wolves_eliminated",
      outcome: {
        kind: "victory",
        primary: { kind: "faction", faction: wolf ? "wolf" : "good", winningPlayerIds: winners },
        additional: [],
        winningPlayerIds: winners,
      },
